; undoc.asm -- appendix B: every undocumented instruction, timed
; generated by genB.py
        INCLUDE "msx.inc"
        OUTPUT "undoc.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM

; Every instruction the manual leaves out, once, between two labels: t
; before it and e after it, where every jump goes. The pointer registers
; point into the RAM, and fix puts them back after each; C is the VDP's
; data port, with the display off, as in Appendix A's times.asm.
