PTR_DE  equ $C100
PTR_HL  equ $C200
PTR_IX  equ $C300
PTR_IY  equ $C400
TOP     equ $F37E               ; the stack, as in chapter 14

init:   di
        ld sp,TOP
        VDP_REG 1, $80          ; display off, no signal from the VDP
        call quick              ; page 2: the cartridge's second half
        call fix
