; fix: the pointer registers back where they belong
fix:    ld bc,PTR_BC
        ld de,PTR_DE
        ld hl,PTR_HL
        ld ix,PTR_IX
        ld iy,PTR_IY
        ret

; quick: page 2 shows page 1's primary slot: port $A8 alone. Uses A, B, C
quick:  in a, (PPI_A)           ; 12
        ld b, a                 ;  5
        and %00001100           ;  8  page 1's primary slot
        add a, a                ;  5
        add a, a                ;  5  moved to page 2's bits
        ld c, a                 ;  5
        ld a, b                 ;  5
        and %11001111           ;  8
        or c                    ;  5
        out (PPI_A), a          ; 12  page 2 = this cartridge, too
        ret                     ; 11
        ASSERT $ <= $C000, the program is longer than the cartridge
        ds $C000 - $, $FF       ; pad the cartridge to 32 KB
